"""Shared configuration for assistant-facing API schemas."""

from pydantic import BaseModel, ConfigDict


class APIResponseModel(BaseModel):
    """Base for data returned by the StudyOps API.

    Unknown response fields are ignored so additive API changes do not break the
    assistant before it has a chance to adopt them.
    """

    model_config = ConfigDict(
        extra="ignore"
    )  # ignore unknown fields in API responses so additive changes do not break the assistant


class ToolInputModel(BaseModel):
    """Base for validated arguments generated by the language model."""

    model_config = ConfigDict(
        extra="forbid",
        str_strip_whitespace=True,
    )  # forbid the model to send more fields than the tool expects, and strip whitespace from string fields
